import React, { useState, useEffect } from 'react';
import { courseService, teacherService } from '../../services/api';
import { toast } from 'react-toastify';
import { FiPlus, FiEdit2, FiTrash2, FiX } from 'react-icons/fi';

const Courses = () => {
  const [courses, setCourses] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingCourse, setEditingCourse] = useState(null);
  const [formData, setFormData] = useState({
    courseCode: '', name: '', description: '', credits: 3, hoursPerWeek: 3, teacherId: '', semester: 1, type: 'LECTURE', maxStudents: 30
  });

  useEffect(() => { fetchData(); }, []);

  const fetchData = async () => {
    try {
      const [coursesRes, teachersRes] = await Promise.all([
        courseService.getAll(),
        teacherService.getAll().catch(() => ({ data: [] }))
      ]);
      setCourses(coursesRes.data);
      setTeachers(teachersRes.data);
    } catch (error) {
      toast.error('Erreur lors du chargement des cours');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const data = { ...formData, teacherId: formData.teacherId ? parseInt(formData.teacherId) : null };
      if (editingCourse) {
        await courseService.update(editingCourse.id, data);
        toast.success('Cours mis à jour avec succès');
      } else {
        await courseService.create(data);
        toast.success('Cours créé avec succès');
      }
      fetchData();
      closeModal();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Une erreur est survenue');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Êtes-vous sûr de vouloir supprimer ce cours ?')) {
      try {
        await courseService.delete(id);
        toast.success('Cours supprimé avec succès');
        fetchData();
      } catch (error) {
        toast.error('Erreur lors de la suppression');
      }
    }
  };

  const openModal = (course = null) => {
    if (course) {
      setEditingCourse(course);
      setFormData({
        courseCode: course.courseCode, name: course.name, description: course.description || '',
        credits: course.credits || 3, hoursPerWeek: course.hoursPerWeek || 3, teacherId: course.teacherId || '',
        semester: course.semester || 1, type: course.type || 'LECTURE', maxStudents: course.maxStudents || 30
      });
    } else {
      setEditingCourse(null);
      setFormData({ courseCode: '', name: '', description: '', credits: 3, hoursPerWeek: 3, teacherId: '', semester: 1, type: 'LECTURE', maxStudents: 30 });
    }
    setShowModal(true);
  };

  const closeModal = () => { setShowModal(false); setEditingCourse(null); };

  const getTeacherName = (teacherId) => {
    const teacher = teachers.find(t => t.id === teacherId);
    return teacher ? `${teacher.firstName} ${teacher.lastName}` : '-';
  };

  if (loading) return <div className="loading"><div className="spinner"></div></div>;

  return (
    <div>
      <div className="header">
        <h1 className="page-title">Gestion des Cours</h1>
        <button className="btn btn-primary" onClick={() => openModal()}><FiPlus /> Ajouter un cours</button>
      </div>

      <div className="card">
        <div className="table-container">
          <table className="table">
            <thead>
              <tr><th>Code</th><th>Nom</th><th>Enseignant</th><th>Crédits</th><th>Semestre</th><th>Type</th><th>Statut</th><th>Actions</th></tr>
            </thead>
            <tbody>
              {courses.length > 0 ? courses.map((course) => (
                <tr key={course.id}>
                  <td>{course.courseCode}</td>
                  <td>{course.name}</td>
                  <td>{getTeacherName(course.teacherId)}</td>
                  <td>{course.credits}</td>
                  <td>S{course.semester}</td>
                  <td>{course.type}</td>
                  <td><span className={`badge badge-${course.status === 'ACTIVE' ? 'success' : 'info'}`}>{course.status}</span></td>
                  <td>
                    <div className="actions">
                      <button className="btn btn-secondary btn-sm" onClick={() => openModal(course)}><FiEdit2 /></button>
                      <button className="btn btn-danger btn-sm" onClick={() => handleDelete(course.id)}><FiTrash2 /></button>
                    </div>
                  </td>
                </tr>
              )) : (
                <tr><td colSpan="8" style={{ textAlign: 'center', color: '#64748b' }}>Aucun cours trouvé</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">{editingCourse ? 'Modifier' : 'Ajouter'} un cours</h2>
              <button className="modal-close" onClick={closeModal}><FiX /></button>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="form-group">
                <label className="form-label">Code du cours</label>
                <input type="text" className="form-control" value={formData.courseCode} onChange={(e) => setFormData({ ...formData, courseCode: e.target.value })} required disabled={!!editingCourse} />
              </div>
              <div className="form-group">
                <label className="form-label">Nom</label>
                <input type="text" className="form-control" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} required />
              </div>
              <div className="form-group">
                <label className="form-label">Description</label>
                <textarea className="form-control" value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} rows="3" />
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                <div className="form-group">
                  <label className="form-label">Crédits</label>
                  <input type="number" className="form-control" value={formData.credits} onChange={(e) => setFormData({ ...formData, credits: parseInt(e.target.value) })} min="1" max="10" />
                </div>
                <div className="form-group">
                  <label className="form-label">Heures/semaine</label>
                  <input type="number" className="form-control" value={formData.hoursPerWeek} onChange={(e) => setFormData({ ...formData, hoursPerWeek: parseInt(e.target.value) })} min="1" max="20" />
                </div>
              </div>
              <div className="form-group">
                <label className="form-label">Enseignant</label>
                <select className="form-select" value={formData.teacherId} onChange={(e) => setFormData({ ...formData, teacherId: e.target.value })}>
                  <option value="">Sélectionner un enseignant</option>
                  {teachers.map(t => <option key={t.id} value={t.id}>{t.firstName} {t.lastName}</option>)}
                </select>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                <div className="form-group">
                  <label className="form-label">Semestre</label>
                  <select className="form-select" value={formData.semester} onChange={(e) => setFormData({ ...formData, semester: parseInt(e.target.value) })}>
                    {[1,2,3,4,5,6,7,8].map(s => <option key={s} value={s}>Semestre {s}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label">Type</label>
                  <select className="form-select" value={formData.type} onChange={(e) => setFormData({ ...formData, type: e.target.value })}>
                    <option value="LECTURE">Cours</option>
                    <option value="LAB">TP</option>
                    <option value="SEMINAR">TD</option>
                    <option value="PROJECT">Projet</option>
                  </select>
                </div>
              </div>
              <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
                <button type="button" className="btn btn-secondary" onClick={closeModal}>Annuler</button>
                <button type="submit" className="btn btn-primary">{editingCourse ? 'Modifier' : 'Créer'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Courses;
